        content: "if-elif-else चा सर्वात वास्तववादी उपयोग म्हणजे श्रेणी देणे. प्रत्येक शिक्षकाला हे करावे लागते: गुणांच्या आधारे विद्यार्थ्याला श्रेणी — उत्कृष्ट, चांगले, पुरेसे किंवा अपुरे. चार श्रेणी म्हणजे चार पर्याय, आणि ते Random हे if-elif-else चेच क्षेत्र आहे.\nरचना अशी: सर्वात उच्च श्रेणीपासून (अपर < अति < चांगले < पुरेसे ...) किंवा सर्वात कमी ते उच्च अशी round सुरू करा. गुण >= 85 तर 'उत्कृष्ट'; गुण >= 60 तर 'चांगले'; गुण >= 35 तर 'पुरेसे'; अन्यथा 'अपुरे'. क्रम नेमका ठेवणे महत्त्वाचे — वरच्या मर्यादा वरून तपासत जा.\nक्रम उलटा लावल्यास त्रास होतो — उदा. आधी >= 35 तपासले तर 90 गुणधारीही 'पुरेसे' म्हणून लगेच थांबेल, कारण पहिली खरी अट जिंकते. म्हणून मोठे गुण आधी, लहान नंतर.\nहे उदाहरण input() सह असल्यास पूर्ण interactive program बनते — वापरकर्ता गुण टाकतो आणि program श्रेणी देतो. int() रूपांतरण आधी करणे, मगच तुलना — हा नियम येथेही तसाच.\nप्रत्येक श्रेणीला स्वतःसाठी वेगळी जुळणी लावा. जर अनेक विद्यार्थ्यांची श्रेणी काढायची असेल तर loop येईल — पण ती पुढील धड्यांची बाब. आत्ता एका विद्यार्थ्याच्या श्रेणीने मांडणी पक्की करा.\nहे उदाहरण चालवून 90, 72, 45, 20, 85 अशा वेगवेगळ्या गुणांवर output तपासा. प्रत्येक वेळी program नेमकी कोणती श्रेणी देतो हे पूर्वाअंदाज करून नंतर चालवा — या सवयीने क्रम आणि सीमा नेमक्या लक्षात येतात.",
