        content: "for loop कोणत्याही मालिकेवर (sequence) चालतो आणि Python मधील मालिकांचे प्रकार अनेक आहेत. list — चौकटीतील item संग्रह, जसे [3, 7, 2]; tuple — रूपांतर न होणारा संग्रह (3, 7, 2); string — अक्षरांची मालिका 'मराठी'; range — संख्यांची क्रमवार मालिका range(4). सर्वांवर for समान प्रकारे चालतो.\nफरक फक्त output मध्ये दिसतो — list च्या प्रत्येक item वेगळा, string चे प्रत्येक अक्षर वेगळे, range चा प्रत्येक अंक वेगळा. रचना एकच: for variable in मालिका:. म्हणून एकदा for चे तत्त्व समजले की चारही प्रकार सहज हाताळता येतात.\nप्रत्येक मालिका for ला 'item देणारा संच' म्हणून पाहता येतो. Python जेव्हा अशी मालिका पाहतो तेव्हा तिचा 'iteration protocol' वापरतो — प्रत्येक फेरीत आपोआप पुढील item निर्माण करतो. या protocol मुळेच मालिका तयार करून for ला दिली की काम होते.\nहे जाणून घेणे महत्त्वाचे आहे की string मधील space (रिकामी जागा) देखील एक अक्षर असते — 'मराठी भाषा' या string मध्ये म, र, ा, ठ, ी, space, भ, ा, ष, ा असे दहा चिन्ह. मागील धड्यातील उदाहरण हेच दाखवते.\nrange ही मालिका विशेषतः महत्त्वाची — for i in range(5) हा कोड नियमित लिहिला जातो. range मध्ये stop मूल्य वगळले जाते (range(5) म्हणजे 0-4), हा नियम बहुतेक फेऱ्यांच्या चुका थांबवतो.\nस्वतः प्रयोग: एकच for ची रचना घेऊन वरील चार मालिकांवर योग्य print लिहा आणि output अभ्यासा. कोणत्या मालिकेवर वेगवेगळे output येतात ते पडताळा.",
