        content: "ज्याप्रमाणे if च्या block मध्ये अनेक ओळी असतात, तसेच for loop च्या block मध्येही अनेक सूचना लिहिता येतात. प्रत्येक घटकासाठी त्या सर्व ओळी वरून खाली क्रमाने चालतात — म्हणजे आपण घटकावर पूर्ण नियंत्रण मिळवतो.\nउदाहरणार्थ, मार्कच्या प्रत्येक गुणांसाठी तीन क्रिया: प्रिंट करा, श्रेणी द्या, चेतावणी द्या. या तीन ओळी block मध्ये ठेवल्यावर प्रत्येक घटकासाठी तिन्ही होतात. किंवा दुकानदार एखादी यादी पाहून प्रत्येक वस्तूला हाताळतो — किंमत, स्टॉक, टॅग.\nloop block चा वापर गोष्टींची बेरीज किंवा यादी सुधारण्यासाठीही होतो. उदा. प्रत्येक वस्तूच्या किंमतीवर GST जोडणे किंवा बेरीज, सरासरी काढणे. अशा क्रियांना कधीकधी accumulator म्हणतात.\nमहत्त्वाची सावधगिरी: loop च्या आत अनेक सूचना असल्यास indentation महत्त्वाची — सर्व ओळी समान तर असल्याच येतात. एक ओळ कमी indentation वर लिहिली तर ती केवळ एकदाच (सुरुवातीला) चालते आणि बाकीच्या प्रत्येक घटकासाठी — हे वर्तन सहज दिसते.\nproactive अभ्यासासाठी loop च्या आत print statement काढून, टाकून प्रयोग करा — block मध्ये कोणती ओळ आहे कोणती बाहेर झाली असेल ते त्वरित लक्षात येते. हा सराव indentation चे महत्त्व पक्के करतो.\nखालील उदाहरणात प्रत्येक मार्क घटकासाठी दोन निर्णय — श्रेणी आणि चेतावणी — क्रमाने चालतात. लूपच्या बाहेरचा शेवटचा print प्रत्यक्षात नेहमी दिसतो.",
