        title: "range च्या मर्यादा — किती मोठा जाऊ शकतो?",
        content: "range ने खूप मोठ्या मालिका पुरवता येतात, पण त्याच्या मर्यादाही जाणून घेण्यासारख्या आहेत. एकदा समजलं की कोणता range वापराल ते ठरवायला मदत होते आणि अनपेक्षित output मुळे वेळ खराब होत नाही.\nmemory फायदा: range संशोधन करता येणारा, पण संपूर्ण मालिका एकाच वेळी memory मध्ये साठवत नाही. त्यामुळे range(1, 10**9) असूनही ती तात्काळ मालिका memory न भरता — फक्त फेऱ्या मोजत जाते.\nपण list(range(1, 10**9)) असे boondonly करायला नको — परिणामप्रेम सर्व memory संपून program गुदमरते. मोठी मालिका हवी तर थेट range सोबत loop वापरा; list फक्त लहान मालिकांवर.\ndigits ची बाब: range ने int मालिकाच येते; float किंवा string मालिका करता येत नाहीत. त्या उद्देशासाठी वेगळे tool लागतील — सध्याच्या धड्याच्या पुढे. आजच्या प्रयोजनासाठी ints च पुरेसे.\nआणखी एक मर्यादा — step नेपद 0 देता येत नाही. range(0, 5, 0) ने ValueError येतो — कारण त्या वेळी मालिका कधीही संपणार नाही. नेहमी step ला शून्येतर द्या.\nशेवटी लक्षात ठेवा — start आणि stop यांच्या तुलनेत step धावतो. stop च्या आधी संपल्यावर उरलेली संख्या सोडली जाते. सराव म्हणून range(1, 30, 7) च्या मालिकेची यादी काढा — output मध्ये 1,8,15,22,29 मिळेल — बरोबर तपासा; अशा तपासण्यांनी range आत्मसात होतो.",
