        content: "range ची संख्या (start, stop, step) लक्षात ठेवल्यास फेऱ्यांची नेमकी मोजणी बदलते. उदा. range(5) मध्ये 5 फेऱ्या — 0 ते 4. range(5, 9) मध्ये 4 — 5,6,7,8. count काढण्यासाठी formula: len(range(start, stop, step)) सहज output देतो.\nstep सोबत मोजणी वेगळी: range(5, 20, 5) — 5,10,15 — म्हणजे 3 फेऱ्या. याचे सूत्र: (stop-start)/step ने नेमक्या फेऱ्या. मिळणारी संख्या अपूर्णांक असेल तर ती वाढवून आकार — पण सहसा Python स्वतः उत्तर देतो.\nखऱ्या प्रोग्राममध्ये ही मोजणी माहीत असणे उपयुक्त — उदा. संगणकातील फेऱ्यांचा अंदाज, timing, स्टॅटस. start आणि stop बदलून मोजणी कशी बदलते याचे experiment करा.\nसराव म्हणून दोन्ही mode वापरा — range(10) आणि range(2, 10, 2) — प्रत्येकाची number ओळ संख्या output करा. तुम्ही पटकन सांगू शकत असाल की outputs काय येतील — मोजणीची पकड.\nदुसरा सराव: range(1, 10) मध्ये सम संख्या काढण्यासाठी for च्या आत if n % 2 == 0: वापरा — condition आणि range संयोग. हे फिल्टरिंग भविष्यातील data कामाचा आधार.\nमोजणी समजल्यावर नेहमी 'किती फेऱ्या' हा प्रश्न आधी विचारा — मग code लिहा. कोड लिहीला तर तो चालतो; पण तुम्हाला मनात कोणती संख्या ठरली हे तपासणे अधिक महत्त्वाचे — आधि उत्तर मनात आणा, नंतर validate करा.",
