        content: "✗ condition बदलणाऱ्या statement विसरणे — counter न वाढवल्यास अट कायम खरी, लूप कधीही संपत नाही. infinite loop ही while ची सर्वात मोठी चूक.\n✗ while चा colon विसरणे — while अट : नंतर block; कॉलन नसेल तर SyntaxError.\n✗ input घेऊन int() न करणे — input मधून string येतो; संख्या तुलना करण्यासाठी int() ने रूपांतरण हवे.\n✗ सुरुवातीचे मूल्य देणे विसरणे — काउंटरला आधी value मिळाली पाहिजे, नाहीतर NameError.\n✗ while True लिहून break विसरणे — अट permanently खरी; थांबण्यासाठी break हवाच.\n✗ for असताना while वापरणे — sequence असेल तर for सोपा व सुरक्षित; while फेऱ्यांची संख्या ठरली नसते तेव्हा.\nलूप कायम चालत राहिला तर Ctrl+C (किंवा Termux मध्ये Ctrl+C) आणि counter बदल तपासा.",
