        content: "while ची सर्वात मोठी ताकद अशी ठिकाणे आहेत जिथे फेऱ्यांची संख्या आधी माहीत नसते — उदा. वापरकर्त्याकडून इनपुट घेऊन थांबवणे. 'योग्य प्रतिसाद मिळेपर्यंत विचारत राहा' हे काम while चेच आहे.\nउदाहरण: अंदाज खेळात दर फेरीत संख्या विचारली जाते आणि बरोबर उत्तर मिळेपर्यंत loop चालतो. फेऱ्यांची संख्या आधी ठरवता येत नाही — त्यामुळे for येथे नापास होतो, whileच निवडतो.\ninput() घेताना ती मूल्य string असते म्हणून int() रूपांतरण आवश्यक. असे रूपांतरण करूनच तुलना गणिताने शुद्ध होते. कोडमध्ये int(input(...)) असा सापडला की समजा — input नंतर रूपांतरण.\nअट नेमकी कशी लिहायची? उदा. while टाकलेला != 5 — जोपर्यंत दिलेली संख्या 5 नाही तोवर फेरी चालत राहते. उत्तर चुकल्यावर 'पुन्हा try' message देतो आणि पुन्हा input मागतो.\nअसे loop वापरकर्त्याच्या प्रतिसादानुसार स्वतः थांबतात — कोणतेही खरे अनिश्चित चाल, सर्व क्षेत्रांमध्ये चालू शकते. पण नेहमी लक्षात ठेवा की संरचना बंद करण्यासाठी अट बदलणारे statement आत असणे आवश्यक आहे.\nखालील program ने बरोबर उत्तर (7) मिळेपर्यंत सतत संख्या विचारतो. output मध्ये पुन्हा try च्या ओळी उत्तराच्या संख्येवर अवलंबून बदलतात; फेऱ्यांची संख्या ठरलेली नाही — हेच while चे स्वरूप.",
