        title: "सामान्य चुका आणि उपाय",
        content: "✗ break ची जागा चुकवणे — break फेरीच्या आत आणि काही अटीनंतर लिहावा; if अटीशिवाय सरळ लिहिल्यास पहिल्याच फेरीत लूप थांबतो.\n✗ continue नंतर कोड ठेवणे — continue नंतरची ओळ वगळली जाते; print continue च्या आधी ठेवावा.\n✗ pass ऐवजी टिप्पणी ठेवणे — फक्त # टिप्पणी block खाली रिकामी जागा ठेवते; तिथे pass हवा.\n✗ break आणि continue चा गोंधळ — break पूर्ण लूप थांबवतो; continue फक्त सद्य फेरी. अर्थ भिन्न आहे.\n✗ while True सह break नाही — अट कायम खरी राहते; infinite loop टाळण्यासाठी बाहेर पडायची स्थिती break ने द्या.\n✗ break नंतर print — break पुन्हा कार्यान्वित होत नाही; break च्या आधीची ओळच print ची दिसते.\n✗ loop-else फरक — else हे loop च्या break न करता संपल्यावरच; break ने संपले तर else वगळले जाते.",
