        content: "break पूर्ण लूप थांबवतो, continue फक्त सद्य फेरी टाकतो, pass ही काहीच न करणारी रिकामी सूचना — ही तीन loop नियंत्रण उपकरणे.\nfor च्या शेवटी असलेला else फक्त ही लूप break न करता संपली तर चालतो — item शोधण्यासाठी असा else उपयोगी ठरतो.\nथोडक्यात: break-else नियम असा — break घडला तर else वगळला जातो; continue पुढील फेरीत उडी मारतो, बाकीच्या फेऱ्या तसल्याच चालतात.",
