        content: "break चा सर्वांत व्यावहारिक उपयोग म्हणजे एखाद्या सूचीत पहिला प्रसंग (इव्हेंट) शोधल्यावर थांबणे. समजा खेळाडूंची यादी दिली आणि पहिला खेळाडू ज्याचे नाव 'राज' च्या अक्षराने सुरू होते तो आपल्याला पुरेसा आहे — संपूर्ण यादी फिरवण्याची गरज नाही.\nअशा वेळी loop मध्ये when आढळले की break बंद करतो — बाकी खेळाडू उडत नाहीत, फेऱ्या वाचतात, आणि program अधिक जलद चालतो. मोठ्या याद्यांमध्ये हीच कार्यक्षमता लक्षणीय ठरते.\nरचना: for खेळाडू in यादी: च्या आत if अट: print; break. find पुरे झाले की नियंत्रण loop च्या पलीकडे जाते. अट N सापडली नाही तर loop संपल्यावर पुढे चालू राहते — break न लागणे इच्छित असेल तर loop-else पहा.\nसराव म्हणून अंकांच्या यादीत पहिली 7 ने विभाज्य संख्या शोधा. वीस संख्यांच्या यादीतून तिसरी अंकांत मिळताच stop — किती फेऱ्या लागल्या हे नोंदवा; output स्पष्ट असावा.\nआपला निकाल output म्हणून स्पष्ट करा — 'सापडले' आणि 'न संपले' अशा दोन शक्यतांना उत्तर द्या. loop संपला तर break न होता सूचना द्या. या प्रकारची रचना searches मध्ये नेहमी असते.\nखाली उदाहरण — यादीत पहिला विषम आधीसम असतो तो printed करून थांबतो. बाकी संख्या न दिसल्याचे लक्षात घ्या — break ने उर्वरित फेऱ्याच दिल्या नाहीत. अशी छोटी उदाहरणे संप करण्याची भावना पक्की करतात.",
