        title: "loop-else — break न झाल्यासच शेवटचा भाग",
        content: "Python मध्ये एक विशेष रचना आहे — loop च्या शेवटी else. त्याचा नियम: loop पूर्ण घोट झाला (break न झाला) तर else चा block चालतो; break झाला तर else वगळला जातो. हे 'तुम्ही संपूर्ण यादी तर शिजवली' दर्शवण्यासाठी उपयुक्त.\nउदा. सूचीत एखादा खास item शोधताना — सापडला तर break; सापडला नाही तर loop संपल्यावर else मध्ये 'सापडला नाही' असे दाखवणे. ही रचना flag वापरण्याच्या जुन्या पद्धतीशिवाय स्पष्ट करते.\nरचना: for item in यादी: if item == खास: print(\"सापडला\"); break else: print(\"सापडला नाही\") — लक्षात घ्या else हा for च्या स्तरावरच आहे, if च्या नव्हे. ही indentation ठीक ठेवणे आवश्यक.\nही रचना वाचतांना 'else' चा अर्थ येथे वेगळाच — Python मध्ये else सोबत for/while देखील येतो; तो 'शेवटी', म्हणजेच सामान्य समाप्तीनंतर. हा अपवाद समजला की गोंधळ कमी.\nउपयुक्त वेळा: सूचीत खात्रीसे rendering, validation — सर्व घटक तपासले गेले असल्याची हमी. break च्या अभावाचा इस्तमास करणारा हा pythonic पर्याय.\nसराव: 1 ते 10 मध्ये 5 शोधा — break होईल म्हणून else दिसणार नाही. आता संख्या 42 शोधा — सापडणार नाही, loop संपेल, else चालू होईल. दोन्ही output तपासा.",
