        content: "आतापर्यंत secret संख्या कोडमध्ये स्थिर होती — 7, 12 अशी. प्रत्येक वेळी तीच असल्यास खेळ एकदा-दोनदा खेळल्यावर कंटाळवाणा होतो. म्हणून random संख्येचा वापर — random module ला import करून random.randint(1, 20) ने प्रत्येक वेळी नवीन secret मिळतो.\nrandom मॉड्यूल ही Python सह येणारी built-in लायब्ररी आहे — अतिरिक्त install नको. सुरुवातीला random.seed() न सांगता प्रत्येक रन वेगळी संख्या देतो, त्यामुळे पुन्हा-पुन्हा output वेगळे दिसते.\nहे समजून घेताना लक्षात ठेवा की random चा वापर करताना चाचणी अवघड होते — कारण threatened output आपण आधी अंदाज करू शकत नाही. म्हणून development दरम्यान secret स्थिर ठेवून debug करा आणि नंतर random जोडा.\nअशी पद्धत (stable first, random later) व्यावसायिकांकडूनही वापरली जाते — अंदाज करणे सोपे ठेवण्यासाठी. output अंदाज करण्याची सवय सोडू नका; random जोडल्यानंतर मात्र 'योग्य श्रेणीत दिसते' एवढीच तपासणी करता येते.\nrandom सुरू करताना काय हवे: import random एकदा वर, नंतर random.randint(1, 20) दररोज नवीन secret. अशी रचना वाचताना तुम्हाला 'कुठे random?' आणि 'कुठे stable?' ते लक्षात घ्या.\nस्वतः खालील project ची एक आवृत्ती random सह लिहा — secret variable मधील संख्या बदलून random.randint(1, 20) लिहा. break च्या नियमांशी संबंध साधून प्रत्येक वेळी वेगळा निकाल अनुभवा.",
