        content: "program मोठा झाला की त्याचे नामकरण आणि रचना निर्णायक बनतात. चांगले नाव variable आणि function चा अर्थ स्वतः समजावते — म्हणून रियाऐवजी स्पष्ट मराठी नावे वापरा: secret, अंदाज, सुमार, बेरीज, गुण. अस्पष्ट x, y टाकणे टाळा.\nकोड वाचताना प्रत्येक block चे काम ओळखता येते ही चांगली रचना आहे. म्हणून प्रत्येक भाग आधी title किंवा comment द्वारे ओळख द्या — पुढील धड्यात function बनवताना हीच सवय कामी येईल.\nआवर्तनParameters (loop variables) ची नावे सुद्धा अर्थपूर्ण ठेवा — i च्या जागी पहाड्यात n, ग्रेडमध्ये empName असे. जर अनेक loops असतील तर i, j अशी लहान नावे गोंधळात टाकतात; आतील अभिजात नावे ठेवण्याचा प्रयत्न करा.\nइंडेंटेशन हे कोड संरचनेचे दुसरे अंग — प्रत्येक block ला सारखे 4 spaces; मिस्कलेल्या tab-spaces मुळे IndentationError येतो. संपादकांमध्ये गिलहरी तपासा: संपूर्ण कोड एकत्र आढळल्यास separator ठेवा.\nकोडमधील जादुई संख्या (magic numbers) टाळण्याचा प्रयत्न करा — 10, 20, 7 अशा संख्या थेट कोडमध्ये येण्याऐवजी शीर्षस्थानी variable म्हणून ठेवा. अशा रचनेने एकाच ठिकाणी बदलून संपूर्ण कोड बदलतो.\nसर्वात महत्त्वाचे: प्रत्येक भाग स्वतंत्रपणे चालवता येईल असा कोड ठेवा — एका भागात दिलेल्या चुकीमुळे दुसरा भाग ग्रस्त होत नाही. अशा 'विभागलेल्या' कोडला debug करणे खूप सोपे असते; पुढील सरावांमध्ये हेच प्रमाण पाळा.",
